 other=ops['res.users'].with_context(no_reset_password=True).create(dict(name='PR22 second operator',login='pr22operator'+str(time.time_ns())+'@example.invalid',company_id=s['company_id'],company_ids=[Command.set([s['company_id']])],group_ids=[Command.set([ops.ref(module+'.group_vpr_pricing_operator').id,ops.ref(module+'.group_vpr_purchase_manager').id,ops.ref('purchase.group_purchase_manager').id,ops.ref('sales_team.group_sale_salesman_all_leads').id])]))
 ops[s['GRANT']].create(dict(company_id=s['company_id'],user_id=other.id,warehouse_ids=[Command.set(s['warehouse'].ids)],allow_cost=True,allow_demand=True,reason='Explicit second execution actor source scope'))
