def fresh(s,uid):
 cr=env.registry.cursor();return cr,api.Environment(cr,uid,s['ctx'])

def apply(a,pid):
 p=a[PLAN].browse(pid);return p.action_apply_approved_vendor_prices(True,p.fingerprint)

def overlap(s,label,first,second,uid1=None,uid2=None):
 held=threading.Event();attempted=threading.Event();finished=threading.Event();out={}
 def a():
  try:
   with env.registry.cursor() as cr:
    a=api.Environment(cr,uid1 or s['mid'],s['ctx']);v=first(a);out['first_id']=v.id if hasattr(v,'id') else None
    held.set();assert attempted.wait(30);time.sleep(.4);assert not finished.is_set(),'Conflicting execution bypassed barrier'
    cr.commit();out['first']='committed'
  except Exception as exc:out['first']=repr(exc);held.set()
 def b():
  assert held.wait(30)
  try:
   with env.registry.cursor() as cr:
    a=api.Environment(cr,uid2 or s['other_uid'],s['ctx']);a[PLAN].search_count([]);attempted.set();second(a);cr.commit();out['second']='committed'
  except SerializationFailure:out['second']='serialization_retry'
  except UserError:out['second']='controlled_conflict'
  except Exception as exc:out['second']=repr(exc)
  finally:finished.set()
 threads=[threading.Thread(target=a),threading.Thread(target=b)]
 for t in threads:t.start()
 for t in threads:t.join(120)
 assert not any(t.is_alive() for t in threads),(label,'timeout')
 assert out['first']=='committed' and out['second'] in ('serialization_retry','controlled_conflict'),(label,out)
 print('PR22_RACE_OUTCOME '+label+' '+str(out),flush=True);return out

